<?php
declare(strict_types=1);

define('DESKBOX_API_ENTRY', true);
require dirname(__DIR__) . '/api/_app/bootstrap.php';
require dirname(__DIR__) . '/api/_app/shared_town.php';
require dirname(__DIR__) . '/api/_app/town_navigation.php';
require dirname(__DIR__) . '/api/_app/town_npcs.php';

$checks = 0;
function life_expect(bool $condition, string $message): void { global $checks; $checks++; if (!$condition) throw new RuntimeException($message); }
function life_reject(string $code, callable $callback): void { try { $callback(); } catch (ApiError $error) { life_expect($error->apiCode === $code, 'Expected ' . $code . ', got ' . $error->apiCode); return; } throw new RuntimeException('Expected ' . $code); }

$pdo = new PDO('sqlite::memory:', null, null, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]);
$pdo->exec('PRAGMA foreign_keys = ON');
$pdo->exec("CREATE TABLE auth_users (id TEXT PRIMARY KEY,username TEXT NOT NULL);
CREATE TABLE town_worlds (world_id TEXT PRIMARY KEY,navigation_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE town_npcs (npc_id TEXT PRIMARY KEY,world_id TEXT NOT NULL,name TEXT NOT NULL,avatar_asset_id TEXT NOT NULL DEFAULT '',appearance_json TEXT NOT NULL,occupation TEXT NOT NULL,enabled INTEGER NOT NULL,agent_paused INTEGER NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE town_npc_profiles (npc_id TEXT PRIMARY KEY,personality_json TEXT NOT NULL,family_background TEXT NOT NULL,short_term_goal TEXT NOT NULL,long_term_goal TEXT NOT NULL,speech_style TEXT NOT NULL,values_json TEXT NOT NULL,fears_json TEXT NOT NULL);
CREATE TABLE town_npc_inventory (npc_id TEXT NOT NULL,item_id TEXT NOT NULL,quantity INTEGER NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(npc_id,item_id));
CREATE TABLE town_player_characters (world_id TEXT NOT NULL,user_id TEXT NOT NULL,display_name TEXT NOT NULL,appearance_asset_id TEXT NOT NULL,appearance_json TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(world_id,user_id));
CREATE TABLE town_npc_homes (npc_id TEXT PRIMARY KEY,home_asset_id TEXT NOT NULL,home_asset_name TEXT NOT NULL,tile_x INTEGER NOT NULL,tile_y INTEGER NOT NULL,interaction_json TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE town_npc_wallets (npc_id TEXT PRIMARY KEY,balance INTEGER NOT NULL,initialized_by TEXT NULL,updated_at TEXT NOT NULL);
CREATE TABLE town_npc_transactions (transaction_id TEXT PRIMARY KEY,seller_npc_id TEXT NOT NULL,buyer_npc_id TEXT NOT NULL,item_id TEXT NOT NULL,quantity INTEGER NOT NULL,amount INTEGER NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE town_npc_wallet_entries (entry_id INTEGER PRIMARY KEY AUTOINCREMENT,npc_id TEXT NOT NULL,entry_type TEXT NOT NULL,delta INTEGER NOT NULL,balance_after INTEGER NOT NULL,transaction_id TEXT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL);
 CREATE TABLE town_npc_decision_policies (npc_id TEXT PRIMARY KEY,decision_interval_seconds INTEGER NOT NULL,observation_interval_seconds INTEGER NOT NULL,dialogue_cooldown_seconds INTEGER NOT NULL,max_decisions_per_hour INTEGER NOT NULL,updated_at TEXT NOT NULL);
 CREATE TABLE town_npc_runtime_states (npc_id TEXT PRIMARY KEY,tile_x INTEGER NOT NULL,tile_y INTEGER NOT NULL,state TEXT NOT NULL,current_task_id TEXT NULL,dialogue TEXT NOT NULL,mood_json TEXT NOT NULL,capabilities_json TEXT NOT NULL,state_version INTEGER NOT NULL,updated_at TEXT NOT NULL);
 CREATE TABLE town_npc_tasks (task_id TEXT PRIMARY KEY,npc_id TEXT NOT NULL,action TEXT NOT NULL,target_id TEXT NOT NULL,payload_json TEXT NOT NULL,status TEXT NOT NULL,failure_reason TEXT NULL,completed_at TEXT NULL);
 CREATE TABLE town_npc_lifecycle (npc_id TEXT PRIMARY KEY,state TEXT NOT NULL,reason_code TEXT NOT NULL,source_event_id INTEGER NULL,started_at TEXT NOT NULL,expected_return_at TEXT NULL,replacement_npc_id TEXT NULL,revision INTEGER NOT NULL,updated_at TEXT NOT NULL);");
$stamp = auth_sql_time(new DateTimeImmutable('2026-11-12T10:00:00Z')); $pdo->exec("INSERT INTO town_worlds VALUES ('main',1)");
$userId = str_repeat('a', 32); $adminId = str_repeat('b', 32); $sellerId = str_repeat('1', 32); $buyerId = str_repeat('2', 32);
$pdo->prepare('INSERT INTO auth_users VALUES (?,?)')->execute([$userId, '测试玩家']); $pdo->prepare('INSERT INTO auth_users VALUES (?,?)')->execute([$adminId, '管理员']);
$insertNpc = $pdo->prepare('INSERT INTO town_npcs VALUES (?,?,?,?,?,?,?,?,?,?)'); foreach ([[$sellerId,'卖家'],[$buyerId,'买家']] as $row) $insertNpc->execute([$row[0],'main',$row[1],'','{}','merchant',1,0,$stamp,$stamp]);
$now = new DateTimeImmutable('2026-11-12T10:00:00Z');
$character = town_npc_ensure_player_character($pdo, $userId, '测试玩家', $now);
life_expect($character['display_name'] === '测试玩家', 'First town entry should create an account character.');
life_expect(town_npc_ensure_player_character($pdo, $userId, '改名', $now)['display_name'] === '测试玩家', 'Existing character must remain stable.');
$home = town_npc_save_home($pdo, $sellerId, ['home_asset_id' => 'house-blue', 'home_asset_name' => '蓝屋', 'tile_x' => 12, 'tile_y' => 18, 'interaction' => ['radius' => 1]], $now);
life_expect($home['home_asset_name'] === '蓝屋' && $home['tile_x'] === 12, 'NPC home should persist asset name and coordinates.');
$policy = town_npc_save_decision_policy($pdo, $sellerId, ['decision_interval_seconds' => 1, 'observation_interval_seconds' => 999999, 'dialogue_cooldown_seconds' => 22, 'max_decisions_per_hour' => 0], $now);
life_expect($policy['decision_interval_seconds'] === 5 && $policy['observation_interval_seconds'] === 86400 && $policy['max_decisions_per_hour'] === 1, 'Decision policy must clamp unsafe frequencies.');
town_npc_set_wallet($pdo, $buyerId, 100, $adminId, $now); town_npc_set_economy_inventory($pdo, $sellerId, ['seed' => 3], $now);
$trade = town_npc_trade($pdo, $sellerId, $buyerId, 'seed', 2, 20, '春季种子', $now);
life_expect($trade['quantity'] === 2, 'Trade should return a durable transaction.');
life_expect((int)$pdo->query("SELECT balance FROM town_npc_wallets WHERE npc_id='$sellerId'")->fetchColumn() === 20, 'Seller receives trade income.');
life_expect((int)$pdo->query("SELECT balance FROM town_npc_wallets WHERE npc_id='$buyerId'")->fetchColumn() === 80, 'Buyer pays from wallet.');
life_expect((int)$pdo->query("SELECT quantity FROM town_npc_inventory WHERE npc_id='$buyerId' AND item_id='seed'")->fetchColumn() === 2, 'Buyer receives traded inventory.');
life_expect((int)$pdo->query('SELECT COUNT(*) FROM town_npc_wallet_entries')->fetchColumn() === 3, 'Initialization and trade ledger entries are retained.');
life_reject('npc_balance_insufficient', static fn() => town_npc_trade($pdo, $sellerId, $buyerId, 'seed', 1, 100, '余额不足', $now));
$balance = town_npc_record_income($pdo, $sellerId, 7, '完成农活', $now);
life_expect($balance === 27, 'Completed work income should increase the NPC wallet.');
$pdo->prepare('INSERT INTO town_npc_inventory (npc_id,item_id,quantity,updated_at) VALUES (?,?,?,?)')->execute([$sellerId, 'bridge_kit', 1, $stamp]);
$pdo->prepare('INSERT INTO town_npc_tasks (task_id,npc_id,action,target_id,payload_json,status,failure_reason,completed_at) VALUES (?,?,?,?,?,?,NULL,NULL)')->execute(['task-life-1', $sellerId, 'work', 'farm-1', '{"consumed_items":{"bridge_kit":1}}', 'running']);
$pdo->prepare('INSERT INTO town_npc_runtime_states (npc_id,tile_x,tile_y,state,current_task_id,dialogue,mood_json,capabilities_json,state_version,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?)')->execute([$sellerId, 10, 10, 'work', 'task-life-1', '', '{}', '[]', 1, $stamp]);
$life = town_npc_transition_lifecycle($pdo, $sellerId, 'absent', '外出办事', $now->modify('+30 minutes'), $now, $adminId);
life_expect($life['state'] === 'absent' && $life['revision'] === 2 && $life['expected_return_at'] !== null, 'NPC lifecycle should enter absent with a bounded return time.');
life_expect(town_npc_transition_lifecycle($pdo, $sellerId, 'absent', '外出办事', $now->modify('+30 minutes'), $now, $adminId)['revision'] === 2, 'Repeating the same lifecycle request must be idempotent.');
life_expect($pdo->query("SELECT status FROM town_npc_tasks WHERE task_id='task-life-1'")->fetchColumn() === 'cancelled', 'Leaving town must cancel the active task.');
$runtimeTaskPointer = $pdo->query("SELECT current_task_id FROM town_npc_runtime_states WHERE npc_id='$sellerId'")->fetchColumn();
life_expect($runtimeTaskPointer === null || $runtimeTaskPointer === false, 'Leaving town must clear the runtime task pointer.');
life_expect((int)$pdo->query("SELECT quantity FROM town_npc_inventory WHERE npc_id='$sellerId' AND item_id='bridge_kit'")->fetchColumn() === 2, 'Leaving town must refund consumed route items.');
life_reject('invalid_lifecycle_transition', static fn() => town_npc_transition_lifecycle($pdo, $sellerId, 'injured', '非法跳转', null, $now, $adminId));
$due = town_npc_recover_due($pdo, $now->modify('+31 minutes'));
life_expect(count($due) === 2 && $due[0]['state'] === 'returning' && $due[1]['state'] === 'active', 'An absent NPC should emit returning and automatically restore to active when its window is reached.');
life_expect(($due[0]['npc_id'] ?? '') === $sellerId && ($due[0]['tile_x'] ?? null) === 10 && ($due[0]['tile_y'] ?? null) === 10, 'Lifecycle recovery deltas should include the NPC identity and authoritative runtime position.');
$active = town_npc_lifecycle($pdo, $sellerId);
life_expect($active['state'] === 'active' && $active['revision'] === 4, 'Returning NPC should be automatically restored to active.');
$injured = town_npc_transition_lifecycle($pdo, $buyerId, 'injured', '需要休养', $now->modify('+30 minutes'), $now, $adminId);
life_expect($injured['state'] === 'injured', 'A second NPC should be able to enter injured.');
$injuredDue = town_npc_recover_due($pdo, $now->modify('+31 minutes'));
life_expect(count($injuredDue) === 2 && $injuredDue[0]['state'] === 'recovering' && $injuredDue[1]['state'] === 'active', 'An injured NPC should emit recovering and automatically restore to active.');
$inactive = town_npc_transition_lifecycle($pdo, $sellerId, 'absent', '再次离镇', $now->modify('+60 minutes'), $now->modify('+35 minutes'), $adminId);
life_expect($inactive['state'] === 'absent', 'The lifecycle guard fixture should be inactive before action checks.');
life_reject('npc_lifecycle_inactive', static fn() => town_npc_apply_action($pdo, ['npc_id' => $sellerId, 'action' => 'rest', 'payload' => []], $now->modify('+36 minutes'), true));
life_expect(town_npc_talk_target($pdo, $sellerId) === null, 'Inactive NPCs must not be valid conversation targets.');
town_npc_transition_lifecycle($pdo, $sellerId, 'returning', 'test_cleanup', null, $now->modify('+37 minutes'), $adminId);
town_npc_transition_lifecycle($pdo, $sellerId, 'active', 'test_cleanup', null, $now->modify('+37 minutes'), $adminId);
$pdo->prepare('INSERT INTO town_npc_tasks (task_id,npc_id,action,target_id,payload_json,status,failure_reason,completed_at) VALUES (?,?,?,?,?,?,NULL,NULL)')->execute(['task-life-advance', $sellerId, 'walk', 'farm-1', '{"route":[{"x":10,"y":10}],"route_cursor":0,"consumed_items":{"bridge_kit":1}}', 'running']);
$pdo->prepare("UPDATE town_npc_runtime_states SET current_task_id='task-life-advance',state='walk' WHERE npc_id='$sellerId'")->execute();
$pdo->prepare("UPDATE town_npc_lifecycle SET state='injured',reason_code='test_advance' WHERE npc_id='$sellerId'")->execute();
$advancedInactive = town_npc_advance_task($pdo, $sellerId, $now->modify('+38 minutes'), true);
life_expect(($advancedInactive['task_status'] ?? '') === 'failed' && ($advancedInactive['failure_reason'] ?? '') === 'npc_lifecycle_inactive', 'Inactive NPC task advancement must cancel safely.');
life_expect($pdo->query("SELECT current_task_id FROM town_npc_runtime_states WHERE npc_id='$sellerId'")->fetchColumn() === null, 'Inactive task advancement must clear the runtime pointer.');
$pdo->prepare("UPDATE town_npc_lifecycle SET state='active',reason_code='' WHERE npc_id='$sellerId'")->execute();
$rows = town_npc_attach_life_data($pdo, [['npc_id' => $sellerId, 'enabled' => 1, 'agent_paused' => 0, 'world_id' => 'main', 'name' => '卖家', 'occupation' => 'merchant', 'appearance_json' => '{}', 'personality_json' => '{}', 'family_background' => '', 'short_term_goal' => '', 'long_term_goal' => '', 'speech_style' => '', 'values_json' => '[]', 'fears_json' => '[]', 'tile_x' => 1, 'tile_y' => 1, 'current_task_id' => null, 'dialogue' => '', 'capabilities_json' => '[]', 'state_version' => 1, 'updated_at' => $stamp, 'runtime_state' => 'rest', 'runtime_updated_at' => $stamp]]);
$public = town_npc_public($rows[0]);
life_expect(($public['home']['home_asset_id'] ?? '') === 'house-blue' && ($public['economy']['balance'] ?? -1) === 27 && ($public['lifecycle']['state'] ?? '') === 'active', 'NPC public snapshot should expose home, economy and lifecycle.');
echo "town_npc_life_test: {$checks} checks ok\n";
